import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    b = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    even = 0
    odd = 0
    possible_cuts = []

    for i in range(n):
        if a[i] % 2 == 0:
            even += 1
        else:
            odd += 1

        if even == odd and i + 1 < n:
            possible_cuts.append(abs(a[i] - a[i + 1]))

    if even != odd:
        print(0)
        return

    possible_cuts.sort()
    ans = 0
    current_sum = 0
    for cost in possible_cuts:
        if current_sum + cost <= b:
            current_sum += cost
            ans += 1
        else:
            break
    print(ans)

if __name__ == "__main__":
    solve()

